const CACHE_NAME='learnwithai-v3';const SHELL=['/','/index.html','/manifest.json','/assets/icons/icon-192x192.svg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE_NAME).then(cache=>Promise.allSettled(SHELL.map(url=>cache.add(url)))));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE_NAME).map(key=>caches.delete(key)))));self.clients.claim();});
self.addEventListener('fetch',event=>{const request=event.request;if(request.method!=='GET'||new URL(request.url).pathname.startsWith('/api/'))return;if(request.mode==='navigate'){event.respondWith(fetch(request).then(response=>{caches.open(CACHE_NAME).then(cache=>cache.put('/index.html',response.clone()));return response;}).catch(()=>caches.match('/index.html')));return;}if(new URL(request.url).origin===self.location.origin){event.respondWith(caches.match(request).then(cached=>cached||fetch(request).then(response=>{if(response.ok)caches.open(CACHE_NAME).then(cache=>cache.put(request,response.clone()));return response;})));}});
self.addEventListener('push',event=>{let data={};try{data=event.data?event.data.json():{};}catch{data={body:event.data?.text()};}event.waitUntil(self.registration.showNotification(data.title||'LearnWithAI note recall',{body:data.body||'Take one minute to revise a saved note.',icon:'/assets/icons/icon-192x192.svg',badge:'/assets/icons/icon-96x96.svg',tag:data.tag||'daily-note-recall',renotify:true,vibrate:[120,80,120],data:{url:data.url||'/#/notes'},actions:[{action:'revise',title:'Revise now'}]}));});
self.addEventListener('notificationclick',event=>{event.notification.close();const target=new URL(event.notification.data?.url||'/#/notes',self.location.origin).href;event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(items=>{const existing=items.find(client=>client.url.startsWith(self.location.origin));if(existing){existing.navigate(target);return existing.focus();}return clients.openWindow(target);}));});
